const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  APPOINTMENT_TERM: s.appointment_term,
  TWILIO_FROM_NUMBER: s.twilio_from_number,
  DAY1_HOURS: s.followup_day1_hours,
  DAY3_HOURS: s.followup_day3_hours,
  DAY7_HOURS: s.followup_day7_hours,
  MAX_ATTEMPTS: s.followup_max_attempts
};

const render = (tpl, vars) => tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] !== undefined && vars[k] !== null) ? vars[k] : '');

const now = new Date();
const allLeads = $input.all().map(i => i.json);

const parseDate = (s) => {
  if (!s) return null;
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
};
const hoursSince = (dateStr) => {
  const d = parseDate(dateStr);
  if (!d) return 9999;
  return (now - d) / (1000 * 60 * 60);
};

// Day-matched templates -- these only reach leads that were NOT auto-scheduled
// (e.g. auto-scheduling failed, or the lead came from a source with no service
// detail yet, like a missed call). Personalized by name + service, no AI cost.
const templates = {
  0: (fn, svc) => render(s.sms_template_followup_day1, { firstName: fn, service: svc, businessName: CONFIG.COMPANY_NAME, appointmentTerm: CONFIG.APPOINTMENT_TERM }),
  1: (fn, svc) => render(s.sms_template_followup_day3, { firstName: fn, service: svc, businessName: CONFIG.COMPANY_NAME, appointmentTerm: CONFIG.APPOINTMENT_TERM }),
  2: (fn, svc) => render(s.sms_template_followup_day7, { firstName: fn, service: svc, businessName: CONFIG.COMPANY_NAME, appointmentTerm: CONFIG.APPOINTMENT_TERM })
};
const dayLabels = ['Day 1', 'Day 3', 'Day 7'];

const qualifying = [];
for (const lead of allLeads) {
  const status = (lead['Status'] || '').trim();
  const count = parseInt(String(lead['Follow-up Count'] || '0'), 10) || 0;
  if (!['New', 'Contacted'].includes(status)) continue;
  if (count >= CONFIG.MAX_ATTEMPTS) continue;

  const raw = String(lead['Phone'] || '').replace(/\D/g, '');
  const e164 = raw.length === 11 && raw.startsWith('1') ? '+' + raw
    : raw.length === 10 ? '+1' + raw : null;
  if (!e164) continue;

  const hours = hoursSince(lead['Last Contact'] || lead['Date Created'] || '');
  const thresholds = { 0: CONFIG.DAY1_HOURS, 1: CONFIG.DAY3_HOURS, 2: CONFIG.DAY7_HOURS };
  if (hours < thresholds[count]) continue;

  const fn = lead['First Name'] || '';
  const svc = lead['Service Needed'] || CONFIG.APPOINTMENT_TERM;
  const msg = templates[count](fn, svc);

  qualifying.push({
    leadId: lead['Lead ID'] || '',
    phone: e164,
    firstName: fn,
    lastName: lead['Last Name'] || '',
    source: lead['Source'] || '',
    email: lead['Email'] || '',
    address: lead['Address'] || '',
    serviceNeeded: svc,
    followUpMessage: msg,
    followUpCount: count + 1,
    newStatus: count >= 2 ? 'Stale' : 'Contacted',
    logChannel: 'SMS',
    logDirection: 'Outbound',
    logHandler: 'System',
    logSummary: 'Follow-up ' + (count + 1) + ' SMS -- ' + dayLabels[count],
    logNotes: msg
  });
}
return qualifying.map(q => ({ json: q }));

const item = $json;
const dayLabels = ['Day 1', 'Day 3', 'Day 7'];
const dayLabel = dayLabels[item.followUpCount - 1] || ('Attempt ' + item.followUpCount);
return [{ json: {
  leadId: item.leadId,
  logChannel: 'SMS',
  logDirection: 'Outbound',
  logHandler: 'System',
  logSummary: 'Follow-up SMS FAILED to send (' + dayLabel + ') -- Follow-up Count not advanced, will retry next run',
  logNotes: item.smsError || 'Unknown Twilio error'
}}];
